export interface AcademyCategorySpec {
  id: string;
  nameBn: string;
  nameEn: string;
  icon: string;
  color: string;
  badge: string;
  descriptionBn: string;
}

export interface AcademyCourseSpec {
  id: string;
  slug: string;
  categoryId: string;
  categoryLabelBn: string;
  titleBn: string;
  titleEn: string;
  subtitleBn: string;
  levelNumber: number; // 0: Foundation, 1: Beginner, 2: Intermediate, 3: Advanced, 4: Professional, 5: Expert
  levelLabel: string;
  courseType: 'Free Course' | 'Certification Course' | 'Practical Lab Course' | 'Bootcamp';
  instructor: string;
  duration: string;
  moduleCount: number;
  lessonCount: number;
  labCount: number;
  quizCount: number;
  assignmentCount: number;
  rating: number;
  enrolledCount: number;
  prerequisiteCourseId?: string;
  skills: string[];
  version: string;
  curriculumOverview?: {
    moduleTitle: string;
    topics: string[];
  }[];
}

export interface CareerLearningPathSpec {
  id: string;
  categoryId: string;
  titleBn: string;
  titleEn: string;
  targetRole: string;
  courseIds: string[];
  badgeName: string;
  estimatedWeeks: number;
  descriptionBn: string;
}

